import json,time,torch
import common as C
torch.set_num_threads(2);C.load();cal=C.batches(C.IDS);small=[(cal[0][0][:4],cal[0][1][:4]),(cal[0][0][4:5],cal[0][1][4:5])];m=C.model('C0',1.25);before={n:v.clone() for n,v in m.state_dict().items()};meta=C.adaptive(m,small);bn=C.bnmap(m);allowed={n+'.'+k for n in bn for k in ('running_mean','running_var','num_batches_tracked')};unchanged=all(torch.equal(v,before[n]) for n,v in m.state_dict().items() if n not in allowed);finite=all(torch.isfinite(x.running_mean).all().item() and torch.isfinite(x.running_var).all().item() and (x.running_var>=0).all().item() for x in bn.values());counts=all(x.num_batches_tracked.item()==2 for x in bn.values());out={'status':'PASSED' if unchanged and finite and counts else 'FAILED','BN_buffers_finite_nonnegative':finite,'all_BN_batch_counts_2':counts,'parameters_and_nonBN_buffers_unchanged':unchanged,'last_batch':1,'wall_seconds':time.monotonic()-C.start,'cpu_seconds':C.cpu(),'forwards':C.counts['forwards'],'samples':C.counts['samples']};C.dump(C.OUT/'preflight/extra_results.json',out);print(json.dumps(out));assert out['status']=='PASSED'
